INSERT INTO `novel_content_novelbasicinfomodel` VALUES (31,'中华上下五千年',3,'中华上下五千年',0,0,3,'2025-07-23 18:12:51.767952','2025-08-02 03:12:47.013275','novel/3/20250723181251_R-C.jpg',1,1,12941,3),(41,'星星之火可以燎原',3,'《星星之火，可以燎原》，是毛泽东在1930年写给林彪的一封信。是为答复林彪散发一封对红军前途究竟应该如何估计征求意见的信。毛泽东在这封信中批评了林彪以及党内一些同志对时局一种悲观的思想。',1,0,3,'2025-08-02 00:15:53.270378','2025-08-02 01:51:29.036426','novel/3/20250802001553_1280.png',1,1,7240,3),(59,'一切反动派都是纸老虎',1,'一切反动派都是纸老虎',0,0,1,'2026-11-18 19:04:12.545885','2026-11-18 19:09:27.347787','',1,1,724,1),(60,'毛泽东选集',1,'毛泽东选集',0,0,2,'2026-11-18 20:53:27.532924','2026-11-18 23:00:32.346786','novel/1/20261118205327_毛泽东选集.jpg',1,2,33676,2),(61,'我是小说网站管理员',4,'我是小说网站管理员',1,0,0,'2026-11-20 20:38:39.581390','2026-11-20 20:39:53.009466','novel/4/20261120203839_admin.jpg',1,2,10,0),(62,'梁山伯与祝英台',1,'梁山伯与祝英台与孟姜女传说、牛郎织女和白蛇传被统称为中国古代四大爱情故事 ，2006年5月20日被列入第一批国家级非物质文化遗产， 有《梁祝辞》为证。 ',1,0,0,'2026-11-20 20:51:09.327990','2026-11-20 21:48:09.479967','novel/1/20261120205109_1795178935283.jpg',1,0,106906,0),(63,'活着',1,'活着 - 余华',1,0,0,'2026-11-20 22:03:12.132670','2026-11-20 22:11:55.556539','novel/1/20261120220312_活着.jpg',1,2,90301,0);
